void remove() {
  swap(a[1], a[n]);
  n--;
  down(1);
}
void down(int x) {
  while (x * 2 <= n) {
    t = x * 2;
    if (t + 1 <= n && a[t + 1] > a[t]) t++;
    if (a[t] <= a[x]) break;
    swap(a[x], a[t]);
    x = t;
  }
}
void build_heap() {
  for (int i = 1; i <= n; i++) 
      up(i);
}
